import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, uniform } from 'three/tsl';
import { PlaneGeometry, Mesh } from 'three/webgpu';

const createNode = (config, ctx) => {
  const { ink, paper, accent, surface } = config.intent?.visualSpec?.colors || {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const surfaceColor = new ctx.THREE.Color(surface);
  const paperColor = new ctx.THREE.Color(paper);

  // Engineered vertical gradient: bottom = surface, top = paper
  const gradientNode = mix(vec3(surfaceColor), vec3(paperColor), uv().y);

  // Geometry: card proportions (2x1.5 units) matching typical card aspect
  const geometry = new PlaneGeometry(2.0, 1.5);
  const material = new MeshBasicNodeMaterial({});
  const mesh = new Mesh(geometry, material);
  mesh.name = 'features-card-3';

  // Temporary placeholder color while texture loads
  material.colorNode = gradientNode;

  // Load brushed metal texture
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      // Mix texture with gradient (subtle grain emphasis)
      material.colorNode = mix(gradientNode, vec3(tex), uniform(0.85));
      tex.needsUpdate = true;
      material.needsUpdate = true;
    }).catch((err) => {
      console.warn('Failed to load brushed metal texture:', err);
    });
  }

  // Cleanup
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    // Texture disposal handled by loader cache; dispose locally if needed
    if (material.map) material.map.dispose();
  };

  // No userData.handlers since no interactions
  mesh.userData.handlers = {};

  return mesh;
};

export default createNode;
